sys_script_include.script:
var createRecord = Class.create();
createRecord.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    cmdbTable: function() {
        var sys = this.getParameter("sys");
        var current = new GlideRecord("x_1583830_it_ass_0_asset_request");
        current.addQuery('sys_id', sys);
        current.query();
        if (current.next()) {
            try {
                var type = current.type_of_asset.getDisplayValue();
                var cmdbTable = '';
                var grA = new GlideRecord('sys_db_object');
                grA.addQuery('name', 'STARTSWITH', 'cmdb_ci');
                grA.addQuery('label', type);
                grA.setLimit(1);
                grA.query();
                if (grA.next()) {
                    cmdbTable = grA.name;
                }

                if (cmdbTable) {

                    var grCmdb = new GlideRecord(cmdbTable);
                    grCmdb.initialize();
                    grCmdb.manufacturer = current.requestor.company;
                    grCmdb.department = current.requestor.department;
                    grCmdb.assigned_to = current.requestor;
                    var cmdbSysId = grCmdb.insert();
                    current.asset = cmdbSysId;
                    current.update();
                }

                var grHardware = new GlideRecord('alm_hardware');
                grHardware.initialize();
                grHardware.manufacturer = current.requestor.company;
                grHardware.department = current.requestor.department;
                grHardware.assigned_to = current.requestor;
                if (cmdbTable) grHardware.ci = cmdbSysId;
                var hardwareSysId = grHardware.insert();

                var grConsumables = new GlideRecord('alm_consumable');
                grConsumables.initialize();
                grConsumables.model = current.consumables;
                grConsumables.model_category = '218323293743100044e0bfc8bcbe5d61';
                grConsumables.parent = hardwareSysId;
                grConsumables.install_status = '2';
                grConsumables.assigned_to = current.requestor;
                grConsumables.location = current.requestor.location;
                grConsumables.insert();
				current.update;
				return true;

            } catch (ex) {
                gs.error('The error is: ' + ex.message);
            }
        } else {
            gs.info("No record found for sys_id: " + sys);
        }
    },


    type: 'createRecord'
});
